style.css:
@-moz-document url-prefix("http://www.carnageblender.com/sidebar.tcl") {
body {
         width: 100%;
         background-color: #100;
         margin-top: -0.6px;
         margin-left: -0.5px;
         font-family: arial narrow;
     }
     body > div:nth-child(11) > h2:nth-child(1) > a:nth-child(1), body > div:nth-child(10) > h2:nth-child(1) > a:nth-child(1) {
         display:none;
     }
     fieldset {
         margin-bottom: 0;
         margin-top: 0;
         margin-left: 0.45em;
         max-width: 89%;
         display: block;
         border-radius: 6px;
         border-top-left-radius: 3px;
         border-bottom-right-radius: 9px;
         border: 7px double #500;
         border-left-style: groove;
         border-left-width: 2px;
         border-top-style: groove;
         border-top-width: 2px;
         border-top-color: #f00;
         border-right-color: #900;
         background-color: #555;
     }
     legend {
         font-family: papyrus;
         color: #fb0;
         text-shadow: 0.5px 0.5px #a00, -0.5px 0.5px #f00, 0.5px -0.5px #500, -0.5px -0.5px #000;
         font-size: 1.2em;
         font-weight: bold;
     }
     td {
         padding-bottom: 0;
         padding-left: 2px;
         ;
     }
     tr:hover {
         background-color: inherit;
     }
     a {
         color: #fed;
         text-shadow: 0.1px 0.1px #888, -0.1px 0.1px #ccc, 0.1px -0.1px #444, -0.1px -0.1px #000;
     }
     a:visited {
         color: #f66;
     }
     a:hover {
         text-shadow: 0.5px 0.5px #000, -0.5px 0.5px #222, 0.5px -0.5px #222, -0.5px -0.5px #444;
         color: #f00;
     }
     ul {
         margin: 0.1em;
         padding: 0.1em;
     }
     li {
         list-style-type: none;
         margin-left: 0;
     }
     #help {
         margin-top: 0;
         margin-left: 0;
     }
     #help li {
         margin-left: 1.2em;
         margin-right: 1em;
         float: left;
     }
     #party_id {
         min-width: 98%;
         max-height: 16px;
         float: right;
         font-family: poor richard;
         font-size: 10pt;
         background-color: #fff;
     }
     #charlinks li {
         margin-right: 2.5em;
         margin-left: 1em;
         display: inline;
     }
     #ba {
         margin-left: 0.4em;
         margin-right: 0.4em;
         font-size: 1.3em;
         font-weight: 500;
         color: #fff;
         text-shadow: 0.5px 0.5px #a00, -0.5px 0.5px #f00, 0.5px -0.5px #500, -0.5px -0.5px #000;
         ;
     }
     #BAWidget > div:nth-child(2) {
         margin-left: 3px;
         font-size: 1.35em;
         text-shadow: 0 0 0.5px #f00, 0 0 0.1em #d00, 0 0 0.2em #b11, 0 0 0.3em #922, 0 0 0.4em #733, 0 0 0.5em #444;
     }
     #opponents {
         position: relative;
         top: -2px;
     }
     #fightlinks li {
         margin-right: 1.5em;
         margin-left: 0.3em;
         font-size: 13px;
         font-weight: normal;
         text-decoration: underline double black;
         display: inline;
     }
     #listbuttons li {
         margin-right: 0.6em;
         margin-left: 0.5em;
         font-family: century gothic;
         font-size: 10.5px;
         display: inline;
     }
     #quicklinks div {
         float: left;
         font-size: 9px;
         letter-spacing: 0.1em;
     }
}
